jsLibrary.noAutoplayNext:
// YouTube desktop: pause when a video ends and keep the Autoplay toggle off.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  function killAutonav() {
    document.querySelectorAll('.ytp-autonav-toggle-button[aria-checked="true"]').forEach((b) => { try { b.click(); } catch (_) {} });
  }
  function hook(video) {
    if (video.__foHooked) return;
    video.__foHooked = true;
    video.addEventListener('ended', () => { try { video.pause(); } catch (_) {} killAutonav(); });
  }
  function sweep() { document.querySelectorAll('video').forEach(hook); killAutonav(); }
  window.__feedoff && window.__feedoff.onSweep(sweep);
  sweep();
})();

jsLibrary.xFollowingOnly:
// X: open Home on "Following", hide the "For you" tab, and mark the Explore page for CSS scoping.
(function () {
  if (!/(^|\.)x\.com$|twitter\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('foryou') !== -1; }
  var last = 0;
  function tabs() {
    var all = document.querySelectorAll('[role="tab"]');
    var forYou = null, following = null;
    all.forEach(function (t) {
      var txt = (t.textContent || '').trim().toLowerCase();
      if (txt === 'for you') forYou = t; else if (txt === 'following') following = t;
    });
    // Other languages: the Home timeline's first two tabs are always For you, then Following.
    if (!forYou && !following) {
      // The tab row sits in the top bar on phones and in the main column on desktop.
      var lists = document.querySelectorAll('[role="tablist"]');
      for (var i = 0; i < lists.length; i++) {
        var own = lists[i].querySelectorAll('[role="tab"]');
        if (own.length >= 2) { forYou = own[0]; following = own[1]; break; }
      }
    }
    return { forYou: forYou, following: following };
  }
  function check() {
    document.documentElement.classList.toggle('feedoff-explore', /^\/explore/.test(location.pathname));
    if (!on() || !/^\/home\/?$/.test(location.pathname)) return;
    var t = tabs(); if (!t.forYou || !t.following) return;
    if (t.forYou.getAttribute('aria-selected') === 'true') {
      var now = Date.now(); if (now - last < 1500) return; last = now;
      try { t.following.click(); } catch (e) {}
    }
    t.forYou.style.setProperty('display', 'none', 'important');
  }
  setTimeout(check, 1200);
  FO && FO.onSweep(check);
  window.addEventListener('popstate', function () { setTimeout(check, 100); });
})();

jsLibrary.ytAdSkip:
// YouTube: if an ad still plays, mute it and jump to its end; click Skip/close when offered.
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('ads') !== -1; }
  var wasMuted = null;
  function tick() {
    if (!on()) return;
    var ad = document.querySelector('.ad-showing, .ad-interrupting, .ytp-ad-player-overlay, ytm-player-ad-overlay, .ytp-ad-preview-container');
    var v = document.querySelector('video');
    if (ad && v) {
      if (wasMuted === null) wasMuted = v.muted;
      v.muted = true;
      if (isFinite(v.duration) && v.duration > 0) { try { v.currentTime = v.duration; } catch (e) {} }
      try { v.playbackRate = 16; } catch (e) {}
    } else if (v && wasMuted !== null) {
      v.muted = wasMuted; wasMuted = null;
      try { if (v.playbackRate === 16) v.playbackRate = 1; } catch (e) {}
    }
    var skip = document.querySelector('.ytp-ad-skip-button, .ytp-ad-skip-button-modern, .ytp-skip-ad-button, button.ytm-skip-ad-button, [class*="skip-button"], [id*="skip-button"]');
    if (skip) { try { skip.click(); } catch (e) {} }
    var close = document.querySelector('.ytp-ad-overlay-close-button, .ytm-ad-overlay-close');
    if (close) { try { close.click(); } catch (e) {} }
  }
  setInterval(tick, 400);
  FO && FO.onSweep(tick);
})();

jsLibrary.ytHomeDesktop:
// YouTube desktop: when the Home feed is hidden, show a small card on / pointing to Subscriptions
// (the redirect handles most visits; this covers in-page navigation back to the logo).
(function () {
  if (!/youtube\.com$/.test(location.hostname)) return;
  var FO = window.__feedoff;
  var ID = '__feedoff_yt_home_hint';
  function on() { return !FO || !FO.enabled || FO.enabled.indexOf('homefeed') !== -1; }
  function check() {
    var onHome = location.pathname === '/' && on();
    document.documentElement.classList.toggle('feedoff-home', onHome);
    var box = document.getElementById(ID);
    if (!onHome) { if (box) box.remove(); return; }
    if (box) return;
    box = document.createElement('div'); box.id = ID;
    box.style.cssText = 'position:fixed;left:50%;top:40%;transform:translate(-50%,-50%);max-width:420px;padding:26px 28px;border-radius:18px;background:rgba(127,127,127,.12);text-align:center;font:15px/1.45 system-ui,sans-serif;color:inherit;z-index:2147483000;';
    var t = document.createElement('div'); t.style.cssText = 'font-weight:700;font-size:18px;margin-bottom:6px;'; t.textContent = 'Home feed hidden';
    var s = document.createElement('div'); s.style.cssText = 'opacity:.75;margin-bottom:16px;'; s.textContent = 'FeedOff keeps YouTube to what you follow and what you search for.';
    var a = document.createElement('a'); a.href = '/feed/subscriptions'; a.textContent = 'Go to Subscriptions';
    a.style.cssText = 'display:inline-block;padding:10px 22px;border-radius:999px;background:#FF6B4A;color:#fff;font-weight:600;text-decoration:none;';
    box.appendChild(t); box.appendChild(s); box.appendChild(a);
    document.body.appendChild(box);
  }
  setTimeout(check, 500);
  FO && FO.onSweep(check);
  window.addEventListener('popstate', function () { setTimeout(check, 100); });
})();
